const headers = $json.headers ?? {};
const tokenHeader = String(headers['x-govhub-token'] || headers['X-GOVHUB-TOKEN'] || '').trim();
const allowed = String($env.GOVHUB_TOKENS || '').split(',').map(v => v.trim()).filter(Boolean);
if (!tokenHeader || !allowed.includes(tokenHeader)) {
  return [{ json: { ok: false, statusCode: 401, error_code: 'AUTH_INVALID_TOKEN', message: 'invalid token' } }];
}
let scopes = [];
try {
  const map = JSON.parse(String($env.GOVHUB_TOKEN_SCOPES_JSON || '{}'));
  if (Array.isArray(map[tokenHeader])) scopes = map[tokenHeader].map((s) => String(s).trim());
} catch {}
if (!(scopes.includes('m:w') || scopes.includes('missions:write') || scopes.includes('s:w'))) {
  return [{ json: { ok: false, statusCode: 403, error_code: 'AUTH_SCOPE_REQUIRED', message: 'missing mission write scope' } }];
}
let body = $json.body ?? $json;
if (typeof body === 'string') {
  try { body = JSON.parse(body); } catch { body = {}; }
}
if (!body || typeof body !== 'object') body = {};
const mission_id = String(body.mission_id || '').trim();
const error_code = String(body.error_code || 'AUTO_FIX_TRIGGER').trim();
const error_excerpt = String(body.error_excerpt || '').trim().slice(0, 256);
if (!mission_id) {
  return [{ json: { ok: false, statusCode: 400, error_code: 'AUTOFIX_INVALID', message: 'mission_id is required' } }];
}
const esc = (v) => String(v ?? '').replace(/'/g, "''");
return [{ json: { ok: true, mission_id, mission_id_sql: esc(mission_id), error_code, error_code_sql: esc(error_code), error_excerpt, error_excerpt_sql: esc(error_excerpt) } }];
